-- Insert Quiz Questions for Lesson: Build a Simple Tagging Structure

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 12 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 12 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'build-tagging-structure' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson build-tagging-structure not found in module 12';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which prefix is used for an Interest tag?', 
    '["ACT-","INT-","STS-","TAG-"]'::jsonb,
    'INT-',
    'INT- is the prefix for Interest tags. ACT- is for Action tags, and STS- is for Status tags.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do when a contact''s status changes from New Lead to Qualified?', 
    '["Keep both STS-New-Lead and STS-Qualified tags","Remove STS-New-Lead and add STS-Qualified","Delete all tags and start over","Only add STS-Qualified without removing anything"]'::jsonb,
    'Remove STS-New-Lead and add STS-Qualified',
    'When status changes, remove the old Status tag and add the new one. A contact should not normally have multiple conflicting Status tags.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which tag best records that someone booked a call?', 
    '["INT-Booked-Call","ACT-Booked-Call","STS-Booked-Call","Booked call 2026"]'::jsonb,
    'ACT-Booked-Call',
    'ACT-Booked-Call is correct because booking a call is an action the contact took. Avoid putting dates in tags like Booked call 2026.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


