-- Insert Quiz Questions for Lesson: Find Contacts with Tags and Smart Lists

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 12 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 12 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'find-contacts-smart-lists' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson find-contacts-smart-lists not found in module 12';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the difference between Match all and Match any when combining tag filters?', 
    '["There is no difference","Match all returns people with BOTH tags; Match any returns people with at least ONE tag","Match all deletes contacts; Match any saves them","Match all is slower than Match any"]'::jsonb,
    'Match all returns people with BOTH tags; Match any returns people with at least ONE tag',
    'Match all returns contacts who have every specified tag. Match any returns contacts who have at least one of the specified tags. Choose based on whether you need all conditions or any condition.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does a Smart List do?', 
    '["It creates a static list that never changes","It saves a filtered view that updates as contacts meet or stop meeting conditions","It deletes contacts that don''t match","It sends emails automatically"]'::jsonb,
    'It saves a filtered view that updates as contacts meet or stop meeting conditions',
    'A Smart List is a saved, dynamic view. Contacts automatically appear when they meet the conditions and disappear when they no longer meet them.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should you save a filtered view as a Smart List?', 
    '["Only if you will never use it again","When the filtered group will be used again","Only for deleted contacts","Never, Smart Lists are not useful"]'::jsonb,
    'When the filtered group will be used again',
    'Save a filtered view as a Smart List when you will use that group of contacts repeatedly. This saves time and ensures the list stays current.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


