      title = 'Keep the Tag List Clean',
      lesson_number = 6,
      sort_order = 6,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Keep the Tag List Clean';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Keep the Tag List Clean

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 12 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 12 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'keep-tag-list-clean' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson keep-tag-list-clean not found in module 12';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you check before renaming or deleting a tag?', 
    '["Nothing, just delete it immediately","Workflows, Smart Lists, campaigns, forms, imports, integrations, and reports that use the tag","Only the tag color","Whether it is the oldest tag"]'::jsonb,
    'Workflows, Smart Lists, campaigns, forms, imports, integrations, and reports that use the tag',
    'Before renaming or deleting a tag, check every place it might be used: workflow triggers and actions, Smart Lists, campaign filters, forms, imports, third-party connections, reports, and manual processes.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the first step in the tag cleanup process?', 
    '["Immediately delete all old tags","Export or record the current tag list","Create new tags without checking existing ones","Rename everything at once"]'::jsonb,
    'Export or record the current tag list',
    'The first step is to export or record the current tag list. This gives you a complete picture before making any changes.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you maintain a tag register?', 
    '["It is required by law","It helps future users understand what each tag means and where it is used","It makes tags automatically apply to contacts","It deletes old tags automatically"]'::jsonb,
    'It helps future users understand what each tag means and where it is used',
    'A tag register documents approved tags, their meanings, and where they are used. This helps team members understand and maintain the tagging system consistently.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
